INIZIO=1

scrivi_impostazione() { # NOME valore
  local nome=$1 valore=$2 tmp
  tmp=$(mktemp)
  grep -vE "^${nome}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$nome" "$valore" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$nome" '%s' "$valore"
  WRITTEN_ENV+=("$nome")
  printf '  %s✓ salvato%s %s → %s\n' "$GREEN" "$RESET" "$nome" "$ENV_FILE"
}

# conferma "domanda": sì/no; accetta s e y (confirm della libreria solo y).
conferma() {
  local risposta=""
  printf '  %s? %s [s/N] %s' "$YELLOW" "$1" "$RESET"
  read -r risposta || true
  [[ "$risposta" =~ ^[SsYy] ]]
}

# Valore salvato nel file (vuoto se manca).
leggi() { _existing "$1" || true; }

# chiedi VAR "domanda" [predefinito]: input visibile; Invio tiene il valore
# già salvato nel file o, se manca, il predefinito.
chiedi() {
  local var=$1 domanda=$2 predefinito=${3:-} attuale risposta=""
  attuale=$(leggi "$var"); [[ -n "$attuale" ]] && predefinito=$attuale
  [[ -n "$predefinito" ]] && domanda+=" [Invio = $predefinito]"
  read -e -r -p "  $domanda " risposta || [[ -n "$risposta" ]] || exit 1
  [[ -z "$risposta" ]] && risposta=$predefinito
  printf -v "$var" '%s' "$risposta"
}

# tappa "Nome": come stage, ma con --da N le tappe prima di N si saltano.
tappa() {
  if (( _STAGE_INDEX + 1 < INIZIO )); then
    _STAGE_INDEX=$((_STAGE_INDEX + 1))
    return 1
  fi
  stage "$1"
  note "(se ti fermi qui, per riprendere: npm run installa-guidata -- --da $((_STAGE_INDEX)))"
  printf '\n'
}

# IPv4 a cui punta un nome, con gli strumenti che ci sono (Linux, macOS, WSL).
risolvi() {
  if command -v getent >/dev/null 2>&1; then
    getent ahostsv4 "$1" 2>/dev/null | awk 'NR==1 {print $1}'
  elif command -v dscacheutil >/dev/null 2>&1; then
    dscacheutil -q host -a name "$1" 2>/dev/null | awk '/^ip_address:/ {print $2; exit}'
  elif command -v dig >/dev/null 2>&1; then
    dig +short A "$1" | tail -n 1
  fi
}

