        PERCORSO=${PERCORSO:-$trovata}
      else
        note "Non trovo ssh-key-*.key in Scaricati/Downloads: scrivi dove l'hai salvata."
        read -e -r -p "  File della chiave scaricata: " PERCORSO || [[ -n "$PERCORSO" ]] || exit 1
      fi
      PERCORSO=${PERCORSO/#\~/$HOME}
      [[ -f "$PERCORSO" ]] && break
      warn "Non trovo il file \"$PERCORSO\"."
    done
    mkdir -p "$HOME/.ssh"
    chmod 700 "$HOME/.ssh"
    mv "$PERCORSO" "$CHIAVE_SSH"
    chmod 600 "$CHIAVE_SSH"
    printf '  %s✓ spostata%s in %s (permessi 600)\n' "$GREEN" "$RESET" "$CHIAVE_SSH"
  fi
  if [[ -n "$(leggi CHIAVE)" ]]; then
    warn "Nel file delle impostazioni c'è una riga CHIAVE=$(leggi CHIAVE): gli script"
    warn "useranno quella, non $CHIAVE_SSH. Se non serve più, toglila."
  fi
  pause "Invio per continuare"
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
if tappa "Dominio gratuito con DuckDNS"; then
  say "Con un dominio l'app ha un nome facile e il lucchetto HTTPS."
  open_url "https://www.duckdns.org"
  step "Accedi (per esempio con Google o GitHub)."
  step "Nel campo \"sub domain\" scrivi un nome (es. tuonome) e premi \"add domain\"."
  step "In alto c'è il token: copialo. È una password, non condividerlo."
  printf '\n'
  while :; do
    chiedi DOMINIO "Il tuo dominio (es. tuonome.duckdns.org):"
    DOMINIO=$(printf '%s' "$DOMINIO" | tr '[:upper:]' '[:lower:]')
    DOMINIO=${DOMINIO#http://}; DOMINIO=${DOMINIO#https://}; DOMINIO=${DOMINIO%/}
    [[ "$DOMINIO" == *.* ]] || DOMINIO="$DOMINIO.duckdns.org"
    [[ "$DOMINIO" =~ $REGEX_DOMINIO && "$DOMINIO" == *.duckdns.org ]] && break
    warn "Scrivi solo il nome, es. tuonome.duckdns.org."
  done
  scrivi_impostazione DOMINIO "$DOMINIO"
  while :; do
    ask_secret DUCKDNS_TOKEN "Incolla il token di DuckDNS (non comparirà):" || return 1
    [[ "$DUCKDNS_TOKEN" =~ ^[A-Za-z0-9-]+$ ]] && break
    warn "Il token è fatto di lettere, cifre e trattini: ricopialo."
  done
  scrivi_impostazione DUCKDNS_TOKEN "$DUCKDNS_TOKEN"

  # L'IP lo comunico io a DuckDNS. Il token passa a curl sullo standard
  # input, non sulla riga di comando.
  IP_SERVER=$(ip_server)
  if [[ -z "$IP_SERVER" ]]; then
    warn "Non so ancora l'IP del server: riprendi con npm run installa-guidata -- --da 7"
    return 1
  fi
  sottodominio=${DOMINIO%.duckdns.org}
  risposta=$(printf 'url = "https://www.duckdns.org/update?domains=%s&token=%s&ip=%s"\n' \
               "$sottodominio" "$DUCKDNS_TOKEN" "$IP_SERVER" | curl -fsS -K - 2>/dev/null || true)
  if [[ "$risposta" == OK ]]; then
    printf '  %s✓%s DuckDNS ora sa che %s è %s\n' "$GREEN" "$RESET" "$DOMINIO" "$IP_SERVER"
  else
    warn "DuckDNS ha rifiutato l'aggiornamento: controlla dominio e token. Puoi anche"
    warn "scrivere l'IP $IP_SERVER a mano nel campo \"current ip\" e premere \"update ip\"."
  fi
  printf '\n'
  say "Controllo che il dominio punti al server (può volerci un minuto)…"
  while :; do
    trovato=$(risolvi "$DOMINIO")
    if [[ "$trovato" == "$IP_SERVER" ]]; then
      printf '  %s✓%s %s → %s\n' "$GREEN" "$RESET" "$DOMINIO" "$trovato"
      break
    fi
    warn "$DOMINIO punta a \"${trovato:-nessun IP}\", non a $IP_SERVER."
    conferma "Riprovo? (n = vado avanti lo stesso)" || break
  done
  pause "Invio per continuare"
fi

# ── 10 ────────────────────────────────────────────────────────────────────
if tappa "Prova del collegamento"; then
  SERVER=$(leggi SERVER)
  say "Provo a entrare nel server $SERVER con la chiave."
  note "La prima volta il PC memorizza l'impronta del server."
  printf '\n'
  until sul_server true; do
    warn "Non riesco a collegarmi. Di solito:"
    note "  - la macchina non è ancora Running, o si sta ancora avviando (aspetta un minuto);"
    note "  - l'IP della tappa 7 è sbagliato (riprendi con --da 7);"
    note "  - la chiave non è quella di questa macchina (riprendi con --da 8)."
    conferma "Riprovo?" || return 1
  done
  printf '  %s✓%s collegamento riuscito\n\n' "$GREEN" "$RESET"
  say "Ora una prova dell'installazione che non tocca niente:"
  printf '\n'
  if ! npm run --silent installa -- --dry-run; then
    warn "La prova si è fermata con un [ERRORE]: il messaggio qui sopra dice cosa sistemare."
    return 1
  fi
  printf '\n'
  pause "Se qui sopra c'è \"Sintassi di installa-server.sh: ok.\", premi Invio"
fi

# ── 11 ────────────────────────────────────────────────────────────────────
if tappa "Installazione sul server"; then
  say "Installo tutto sul server: Node.js, PostgreSQL, Caddy (HTTPS), firewall,"
  say "aggiornamenti automatici, backup notturni e l'app. Dura alcuni minuti e"
  say "scorrono molte righe: è normale, anche gli avvisi \"perl: warning: ... locale\"."
  printf '\n'
  conferma "Avvio l'installazione?" || { say "Quando vuoi: npm run installa-guidata -- --da 11"; return 1; }
  until npm run --silent installa; do
    warn "L'installazione si è fermata: il motivo è nel messaggio [ERRORE] qui sopra."
    note "Rilanciarla è sicuro: non rifà quello che c'è già e non cancella i dati."
    conferma "Riprovo?" || return 1
  done
  pause "Invio per continuare"
fi

# ── 12 ────────────────────────────────────────────────────────────────────
if tappa "Primo accesso"; then
  DOMINIO=$(leggi DOMINIO); SERVER=$(leggi SERVER)
  open_url "https://$DOMINIO"
  note "Se il lucchetto non c'è ancora, aspetta un minuto e ricarica."
  step "Scegli Registrati, poi nome utente e password."
  step "Manda il link ai tuoi amici: ognuno si registra da solo."
  printf '\n'
  say "Il catalogo all'inizio è vuoto: il server scarica i set ogni giorno alle 05:00."
  if conferma "Lo scarico adesso? (da qualche minuto a mezz'ora)"; then
    if sul_server "sudo -u pokeportfolio -H bash -c 'cd /opt/pokeportfolio && node --env-file=.env server/scripts/job.js catalog-sync'"; then
      printf '  %s✓%s catalogo scaricato: ricarica la pagina.\n' "$GREEN" "$RESET"
    else
      warn "Lo scaricamento non è riuscito: ci pensa il server stanotte alle 05:00."
    fi
  fi
  pause "Invio per continuare"
fi

# ── 13 ────────────────────────────────────────────────────────────────────
if tappa "Backup fuori dal server (facoltativo): permessi"; then
  say "I backup notturni restano sul disco del server: se la macchina si perde, si"
  say "perdono con lei. Puoi copiarli ogni notte in un bucket di Oracle Object Storage"
  say "(gratis fino a 20 GB). Il server potrà solo AGGIUNGERE copie, non cancellarle;"
  say "quelle più vecchie di 30 giorni le cancella Oracle."
  printf '\n'
  if ! conferma "Vuoi attivarlo?"; then
    chiusura
    note "Il backup fuori dal server puoi attivarlo quando vuoi:"
    note "  npm run installa-guidata -- --da 13"
    printf '\n'
    return 0
  fi
  printf '\n'
  open_url "https://cloud.oracle.com/"
  step "La regione è in alto a destra nel pannello (es. eu-milan-1, eu-frankfurt-1)."
  while :; do
    chiedi REGIONE "Regione:"
    [[ "$REGIONE" =~ ^[a-z]+-[a-z]+-[0-9]+$ ]] && break
    warn "Scrivi l'identificativo, es. eu-milan-1 (non il nome \"Italy Northwest\")."
  done
  step "Menu ☰ → Compute → Instances → la tua macchina → scheda Details, riga OCID → Copy."
  while :; do
    chiedi OCID_ISTANZA "OCID della macchina (inizia con ocid1.instance.):"
    [[ "$OCID_ISTANZA" =~ ^ocid1\.instance\.[A-Za-z0-9._-]+$ ]] && break
    warn "Non sembra l'OCID di una macchina: deve iniziare con ocid1.instance."
  done
  while :; do
    chiedi GRUPPO "Nome del gruppo della macchina:" pokeportfolio-server
    [[ "$GRUPPO" =~ $REGEX_NOME_OCI ]] && break
    warn "Solo lettere, cifre, punti e trattini."
  done
  while :; do
    chiedi OCI_BUCKET_BACKUP "Nome del bucket:" pokeportfolio-backup
    [[ "$OCI_BUCKET_BACKUP" =~ $REGEX_NOME_OCI && "$OCI_BUCKET_BACKUP" != nessuno ]] && break
    warn "Solo lettere, cifre, punti e trattini."
  done
  _clear
  printf '\n%s%s▸ Stage %s/%s · Backup: gruppo e policy%s\n\n' "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$RESET"
  say "1) Il gruppo della macchina."
  step "Menu ☰ → Identity & Security → Domains → Default → scheda Dynamic groups"
  note "    → Create dynamic group. Nome: $GRUPPO. Regola:"
  printf '\n      %s\n\n' "instance.id = '$OCID_ISTANZA'"
  pause "Invio quando il gruppo è creato"
  printf '\n'
  say "2) I permessi."
  step "Menu ☰ → Identity & Security → Policies. Scegli il compartment principale"
  note "    (la radice, con il nome del tuo account) → Create Policy."
  step "Nome: pokeportfolio-backup. Attiva \"Show manual editor\" e incolla:"
  printf '\n'
  printf '%s\n' \
    "Allow dynamic-group 'Default'/'$GRUPPO' to read buckets in tenancy where target.bucket.name = '$OCI_BUCKET_BACKUP'" \
    "Allow dynamic-group 'Default'/'$GRUPPO' to manage objects in tenancy where all {target.bucket.name = '$OCI_BUCKET_BACKUP', any {request.permission = 'OBJECT_CREATE', request.permission = 'OBJECT_INSPECT'}}" \
    "Allow service objectstorage-$REGIONE to manage object-family in tenancy"
  printf '\n'
  note "Le prime due righe permettono al server solo di caricare copie nuove e di"
  note "elencarle; la terza permette a Oracle di cancellare quelle vecchie."
  pause "Invio quando la policy è creata"
fi

# ── 14 ────────────────────────────────────────────────────────────────────
if tappa "Backup fuori dal server (facoltativo): bucket"; then
  [[ -n "${OCI_BUCKET_BACKUP:-}" ]] || chiedi OCI_BUCKET_BACKUP "Nome del bucket (lo stesso scritto nella policy):" pokeportfolio-backup
  open_url "https://cloud.oracle.com/"
  step "Menu ☰ → Storage → Buckets → Create Bucket."
  note "    Nome: $OCI_BUCKET_BACKUP. Lascia Standard e lascialo privato. Create."
  step "Apri il bucket → Lifecycle Policy Rules → Create Rule:"
  note "    nome cancella-dopo-30-giorni, Lifecycle Action: Delete, Number of days: 30,"
  note "    regola attiva → Create."
  note "  Errore di permessi? Ricontrolla la terza riga della policy e riprova fra qualche minuto."
  pause "Invio quando bucket e regola sono creati"
  printf '\n'
  scrivi_impostazione OCI_BUCKET_BACKUP "$OCI_BUCKET_BACKUP"
  printf '\n'
  say "Ora rilancio l'installazione, che attiva la copia dei backup."
  if conferma "Procedo?"; then
    if npm run --silent installa; then
      note "Se alla fine c'è un [ATTENZIONE] sul bucket, i permessi nuovi non valgono"
      note "ancora: aspetta qualche minuto e rilancia npm run installa."
    else
      warn "L'installazione si è fermata: il motivo è nel messaggio [ERRORE] qui sopra."
    fi
  else
    note "Quando vuoi: npm run installa"
  fi
  pause "Invio per finire"
fi

chiusura
}

run_wizard "$@"; exit
